\begin{problem}{1}
Suppose $a$ and $b$ are real numbers, not both $0$.  Find real numbers $c$ and $d$ such that 
\begin{equation*}
\frac{1}{a+bi}=c+di
\end{equation*}
\end{problem}
\begin{proof}
We have
\begin{align*}
\frac{1}{a+bi} &= \frac{a-bi}{a^2+b^2} = \frac{a}{a^2+b^2} - \frac{b}{a^2+b^2}i,
\end{align*}
and hence let
\begin{equation*}
c = \frac{a}{a^2+b^2}, ~~~ d = - \frac{b}{a^2+b^2},
\end{equation*}
and we're done.
\end{proof}

