List<int> generateRandom(int seed, int length, int rangeStart, int rangeEnd) {
  final List<int> result = [];
  int current = seed;

  for (int i = 0; i < length; i++) {
    current = ((current * 0x41C64E6D) ^ current) >> 30;
    int randomNumber = rangeStart + (current.abs() % (rangeEnd - rangeStart));
    result.add(randomNumber);
  }

  return result;
}

